class Trie {
  constructor() {
    this.root = {};
  }
  insert(word) {
    let node = this.root;
    for (const c of word) {
      if (!node[c]) node[c] = {};
      node = node[c];
    }
    node.end = true;
    return this;
  }
  _walk(prefix) {
    let node = this.root;
    for (const c of prefix) {
      if (!node[c]) return null;
      node = node[c];
    }
    return node;
  }
  search(word) {
    const node = this._walk(word);
    return Boolean(node && node.end);
  }
  startsWith(prefix) {
    return this._walk(prefix) !== null;
  }
}

