class WordDictionary {
  constructor() {
    this.root = {};
  }
  addWord(word) {
    let node = this.root;
    for (const c of word) {
      if (!node[c]) node[c] = {};
      node = node[c];
    }
    node.end = true;
    return this;
  }
  search(word) {
    const dfs = (node, i) => {
      if (i === word.length) return Boolean(node.end);
      const c = word[i];
      if (c === ".") {
        for (const key of Object.keys(node)) {
          if (key !== "end" && dfs(node[key], i + 1)) return true;
        }
        return false;
      }
      if (!node[c]) return false;
      return dfs(node[c], i + 1);
    };
    return dfs(this.root, 0);
  }
}

function findWords(board, words) {
  const rows = board.length;
  const cols = board[0].length;
  const root = {};
  for (const w of words) {
    let node = root;
    for (const c of w) {
      if (!node[c]) node[c] = {};
      node = node[c];
    }
    node.word = w;
  }
  const out = new Set();
  const dfs = (r, c, node) => {
    const ch = board[r][c];
    if (!node[ch]) return;
    node = node[ch];
    if (node.word) {
      out.add(node.word);
      delete node.word;
    }
    board[r][c] = "#";
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== "#") {
        dfs(nr, nc, node);
      }
    }
    board[r][c] = ch;
  };
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < cols; c += 1) dfs(r, c, root);
  }
  return [...out];
}
